L = list(L)
# Precompute all possible triples a<b<c with a+b=c
triples = [(a,b,c) for a,b,c in itertools.permutations(L,3) if a+b==c]
# Use backtracking to find 15 disjoint triples covering all numbers
used=set()
solution=[]

def backtrack(start, used, sol):
    if len(sol)==15:
        return sol
    for i in range(start, len(triples)):
        a,b,c = triples[i]
        if a in used or b in used or c in used:
            continue
        new_used = used | {a,b,c}
        res = backtrack(i+1, new_used, sol+[(a,b,c)])
        if res:
            return res
    return None

res = backtrack(0, set(), [])
